def total_even(nums):
    result = []
    for n in nums:
        if n % 2 == 0:
            result.append(n)
    return sum(result)

print(total_even([1, 2, 3, 4, 5, 6]))

def find_max(nums):
    biggest = 0
    for n in nums:
        if n > biggest:
            biggest = n
    return biggest

print(find_max([-5, -2, -9]))
